"use client";
import {useCallback,useEffect,useRef,useState} from 'react';
import {formText,hotelClient,hotelRpc} from '@/lib/pilot';
import type {HandoffScope} from '@/lib/cashier-handoff';
import {checkedStatement,statementArgs,statementMinor,readStatementReceipt,type StatementRequest} from '@/lib/cashier-bank-statement-request';
export function CashierBankStatementCreate({scope,account,onSaved}:{scope:HandoffScope;account:string;onSaved:()=>void}){
 const key='irp.statement.v1:'+ [scope.tenant,scope.property,scope.actor,account].join(':');
 const [pending,setPending]=useState<StatementRequest|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState(''),[restored,setRestored]=useState(false),[storageBlocked,setStorageBlocked]=useState(false);const alive=useRef(false),lock=useRef(false);
 const read=useCallback(()=>{const raw=sessionStorage.getItem(key);if(raw===null)return null;const r=checkedStatement(JSON.parse(raw));if(r.account!==account)throw Error('Pending statement account changed.');return r},[key,account]);
 useEffect(()=>{alive.current=true;const timer=setTimeout(()=>{try{setPending(read())}catch(e){setStorageBlocked(true);setError(e instanceof Error?e.message:'Unable to recover statement.')}finally{if(alive.current)setRestored(true)}},0);return()=>{clearTimeout(timer);alive.current=false}},[read]);
 async function identify(){const u=await hotelClient().auth.getUser();if(u.error||u.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen statement entry.')}
 async function save(request:StatementRequest,status=false){if(lock.current)return;lock.current=true;setBusy(true);setError('');setMessage('');try{
  const r=checkedStatement(request);if(r.account!==account)throw Error('Statement account changed.');await identify();if(!alive.current)return;const prior=read(),encoded=JSON.stringify(r);if(prior&&JSON.stringify(prior)!==encoded)throw Error('Recover the pending statement first.');sessionStorage.setItem(key,encoded);if(sessionStorage.getItem(key)!==encoded)throw Error('Unable to preserve statement recovery.');setPending(r);
  const value=await hotelRpc(status?'cashier_bank_reconciliation_status':'record_cashier_bank_statement',status?{p_tenant:scope.tenant,p_property:scope.property,p_request:r.id,p_kind:'statement'}:statementArgs(r,scope));await identify();if(!alive.current)return;
  if(!readStatementReceipt(value,r,scope,status)){setMessage('No saved statement found. Retry the original entry.');return}
  const current=read();if(current&&JSON.stringify(current)!==encoded)throw Error('A different statement is pending.');sessionStorage.removeItem(key);if(sessionStorage.getItem(key)!==null)throw Error('Unable to clear statement recovery.');setPending(null);setMessage('Statement item recorded for manual reconciliation.');onSaved();
 }catch(e){if(alive.current)setError(e instanceof Error?e.message:'Statement interrupted. Check its saved result.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 const [cancelConfirmed,setCancelConfirmed]=useState(false);
 async function cancel(){if(lock.current||!pending||!cancelConfirmed)return;const request=pending.id;lock.current=true;setBusy(true);setError('');setMessage('');try{await identify();if(!alive.current)return;const v=await hotelRpc('cancel_cashier_reconciliation_action',{p_tenant:scope.tenant,p_property:scope.property,p_request:request,p_kind:'statement',p_confirmed:true}) as Record<string,unknown>;await identify();if(!alive.current)return;if(!v||v.schema_version!==1||v.tenant_id!==scope.tenant||v.property_id!==scope.property||v.actor_id!==scope.actor||v.request_id!==request||v.kind!=='statement'||v.cancelled!==true||typeof v.replayed!=='boolean'||typeof v.created_at!=='string')throw Error('Cancellation receipt does not match the pending request.');const current=read();if(current&&current.id!==request)throw Error('A different request is pending.');sessionStorage.removeItem(key);if(sessionStorage.getItem(key)!==null)throw Error('Unable to clear cancelled request.');setPending(null);setCancelConfirmed(false);setMessage('Unsaved request cancelled. Delayed retries cannot create it.')}catch(e){if(alive.current)setError(e instanceof Error?e.message:'Cancellation interrupted. Retry to confirm its result.')}finally{lock.current=false;if(alive.current)setBusy(false)}}
 if(!restored)return <section><h3>Record statement item</h3><p>Checking for an interrupted statement entry…</p></section>;
 if(storageBlocked)return <section><h3>Record statement item</h3><p className="pilot-error" role="alert">{error||'A saved statement request needs manager review.'}</p><p>Do not create another statement entry until the saved request is recovered or cleared by a manager.</p></section>;
 return <section><h3>Record statement item</h3><p>Copy a credit or debit from your bank statement. Use a unique statement reference for this account.</p>{pending?<><label><input type="checkbox" checked={cancelConfirmed} disabled={busy} onChange={e=>setCancelConfirmed(e.target.checked)}/>Cancel this unsaved request.</label><button disabled={busy||!cancelConfirmed} onClick={()=>void cancel()}>Cancel pending request</button><p>Pending statement: {pending.reference}</p><button disabled={busy} onClick={()=>void save(pending)}>Retry statement entry</button><button disabled={busy} onClick={()=>void save(pending,true)}>Check statement entry</button></>:<form onSubmit={e=>{e.preventDefault();try{const f=new FormData(e.currentTarget);void save({id:crypto.randomUUID(),account,amount:statementMinor(formText(f,'amount').trim(),formText(f,'direction')),date:formText(f,'date'),reference:formText(f,'reference').trim(),description:formText(f,'description').trim()})}catch(e){setError(e instanceof Error?e.message:'Review statement details.')}}}><fieldset disabled={busy}><label>Statement direction<select name="direction"><option value="credit">Credit</option><option value="debit">Debit</option></select></label><label>Statement amount<input name="amount" inputMode="decimal" required/></label><label>Statement date<input name="date" type="date" required min="1900-01-01"/></label><label>Statement reference<input name="reference" required minLength={2} maxLength={120}/></label><label>Statement description<input name="description" required minLength={2} maxLength={500}/></label><label><input type="checkbox" required/>I checked this item against the bank statement.</label><button>Record statement item</button></fieldset></form>}{error&&<p role="alert">{error}</p>}{message&&<output className="pilot-notice">{message}</output>}</section>
}
